import hashlib


class RecordProgram:
    """Recomputes the record's checkable result."""

    def __init__(self):
        self.figures = {"release_runs_required": 2, "tests_per_run": 18, "training_runs": 6, "tuning_changes": 23}

    def run(self):
        total = sum(self.figures.values())
        return {"total": total,
                "digest": hashlib.sha256(str(total).encode()).hexdigest()}
